#include <stdio.h>
// 영이면 끝내고 돌아오며 더해요.
int sum(int n) { return n == 0 ? 0 : n + sum(n - 1); }
int main(void) {
    printf("%d\n", sum(3));
    return 0;
}

class Report {
    // 생성 횟수는 공유하고 수량은 각 객체에 둬요.
    static int count = 0;
    int qty = 3;
    Report() { count++; }
}

public class Main {
    public static void main(String[] args) {
        Report first = new Report();
        Report second = new Report();
        second.qty = 8;
        System.out.println(Report.count + ":" + first.qty);
    }
}

class Report { int read() { return 3; } }
class Child extends Report {
    // 같은 호출을 자식에서 바꿔요.
    @Override int read() { return 9; }
}

public class Main {
    public static void main(String[] args) {
        Report report = new Child();
        System.out.println(report.read());
    }
}

-- 일치하지 않은 상품도 남겨 전체 행을 세어요.
SELECT COUNT(*) FROM product p
LEFT JOIN orders o ON p.id = o.product_id;

-- 그룹별 합을 만든 뒤 조건에 맞는 그룹 수를 세어요.
SELECT COUNT(*) FROM (
 SELECT category FROM stock
 GROUP BY category HAVING SUM(qty) > 3
) AS totals;
